// Villages: five village types, each with its own buildings, generated by the jigsaw engine.
//
// From the wiki (`Village`, `Village/Structure`, `Village/Loot`; saved under docs/structure-audit/wiki/):
//   * Plains (plains, meadow), desert, savanna, taiga and snowy (snowy plains) villages. The type comes from the biome
//     at the meeting point, and each type has its own architecture, materials and building set.
//   * A village is a meeting point with a bell, streets, and buildings drawn at random from the type's pool: houses
//     with beds (one villager per bed), job-site buildings (no beds, no villagers), farms, animal pens, temples and
//     decorations, with lamp posts. No village has every building.
//   * One iron golem near the meeting point; one camel at the meeting point of a desert village; livestock (cows,
//     sheep, pigs, horses) in pens; cats, one for every four beds up to five; two armour stands at a taiga armorer.
//   * 2% of villages are ABANDONED: zombie villagers instead of villagers, no doors and no torches, most cobblestone
//     mossy, some wood replaced by cobwebs, brown stained glass panes, no iron golem and no camel; cats and
//     livestock still spawn.
//   * Paths are dirt paths and grass (smooth sandstone in the desert).
//
// The building catalogue is villageCatalogue.js, the materials villageStyles.js and the builders villageBuild.js.
// PROVENANCE: no Minecraft assets -- every element is built by code from the wiki's descriptions.

import { StructureStart } from '../start.js';
import { LegacyRandom, legacyFromLargeFeatureSeed } from '../random.js';
import { TemplatePool, TemplatePoolRegistry, PoolElement, addPieces } from '../jigsaw.js';
import { BlockBox } from '../geometry.js';
import { StructureTemplate } from '../template.js';
import { placeTemplate } from '../templatePlacement.js';
import { createBlockIdResolver } from '../blockIds.js';
import { STYLES, VILLAGE_TYPE_OF } from './villageStyles.js';
import { CATALOGUE, houseEntries, weightOf } from './villageCatalogue.js';
import { VILLAGE_WIKI } from '../../villageWikiData.js';
import {
  buildVillageElement, STREET_SLOT, HOUSE_SLOT, STREET_POOL, HOUSE_POOL, MEETING_CAT_SPOTS
} from './villageBuild.js';

export { STREET_SLOT, HOUSE_SLOT, STREET_POOL, HOUSE_POOL };

/** Per registry id: the type's biome, path block and house loot table (kept for callers that read them). */
export const VILLAGE_BIOMES = Object.fromEntries(Object.entries(VILLAGE_TYPE_OF).map(([id, type]) => [id, {
  type, biome: STYLES[type].biome, path: 'minecraft:' + STYLES[type].path,
  loot: `minecraft:chests/village/village_${type}_house`, crops: STYLES[type].crops
}]));

// Vanilla: "size": 6 and "max_distance_from_center": 80 for every village.
export const VILLAGE_MAX_DEPTH = 6;
export const VILLAGE_MAX_DISTANCE = 80;

/** The wiki: "A village has a 2% chance of generating as an abandoned village". */
export const ABANDONED_CHANCE = 0.02;
/** Pool weights that make that exact: each normal meeting point weighs 49, each abandoned one 1, so 1 in 50. */
const MEETING_WEIGHT = 49;
const ABANDONED_MEETING_WEIGHT = 1;
const ABANDONED_PREFIX = 'zombie/';

/** The wiki: "one cat for every four beds, up to five". */
export const BEDS_PER_CAT = 4;
export const MAX_VILLAGE_CATS = 5;

const STREET_WEIGHT = 4;
const TERMINUS_WEIGHT = 1;
/**
 * Empty plots: the share of a house pool that is vanilla's empty element (a street-side spot left unbuilt). The wiki
 * gives no numbers, only that abandoned villages can have slightly more buildings; these shares are ours.
 */
export const EMPTY_PLOT_SHARE = 0.15;
export const ABANDONED_EMPTY_PLOT_SHARE = 0.04;
const emptyElement = (share, weights) => {
  const total = weights.reduce((sum, w) => sum + w, 0);
  return new PoolElement({ type: 'minecraft:empty_pool_element', name: 'empty', weight: Math.max(1, Math.round((total * share) / (1 - share))) });
};

// The abandoned variant has its own pools, as vanilla does (village/<type>/zombie/...): an abandoned meeting point leads
// into abandoned streets, and those draw from the type's zombie house list on the wiki -- mostly houses, without most
// of the farms, pens, job sites and decorations. That is why "the number of buildings in an abandoned village can be
// slightly more than in a normal village".
export const ZOMBIE_STREET_POOL = 'village/zombie/streets';
export const ZOMBIE_HOUSE_POOL = 'village/zombie/houses';
/** The wiki's zombie house list for a type, limited to buildings (it also lists two plains meeting points). */
export function zombieHouseNames(type) {
  return (VILLAGE_WIKI.zombieHouses[type] ?? []).filter((name) => villageElement(type, name)?.role === 'building');
}

/** Every catalogue entry by its element name, per type, with its role for the builder. */
function elementsOf(type) {
  const cat = CATALOGUE[type];
  const lamps = cat.lamps ?? [cat.lamp];
  return new Map([
    ...cat.meetings.map((e) => [e.name, { ...e, role: 'meeting' }]),
    ['street', { name: 'street', role: 'street' }],
    ['terminus', { name: 'terminus', role: 'terminus' }],
    ...lamps.map((e) => [e.name, { ...e, role: 'lamp' }]),
    ...houseEntries(type).map((e) => [e.name, { ...e, role: 'building' }])
  ]);
}
const ELEMENTS = Object.fromEntries(Object.keys(CATALOGUE).map((type) => [type, elementsOf(type)]));

/** The catalogue entry for an element name (an abandoned meeting point is its normal one). */
export function villageElement(type, name) {
  return ELEMENTS[type].get(name.startsWith(ABANDONED_PREFIX) ? name.slice(ABANDONED_PREFIX.length) : name) ?? null;
}

/** A built element, memoised per type: a village is realized once per chunk it touches. */
const TEMPLATE_CACHE = new Map();
function templateFor(type, name) {
  const key = type + '/' + name;
  let template = TEMPLATE_CACHE.get(key);
  if (!template) {
    const entry = villageElement(type, name);
    if (!entry) throw new Error(`village: no ${type} element ${name}`);
    const data = buildVillageElement(type, entry, CATALOGUE);
    if (name.startsWith(ABANDONED_PREFIX)) {
      // The same piece, with its streets and houses pointing into the abandoned pools.
      const swap = { [STREET_POOL]: ZOMBIE_STREET_POOL, [HOUSE_POOL]: ZOMBIE_HOUSE_POOL };
      data.blocks = data.blocks.map((b) => (b.nbt && swap[b.nbt.pool] ? { ...b, nbt: { ...b.nbt, pool: swap[b.nbt.pool] } } : b));
    }
    template = new StructureTemplate(data, 'minecraft:village/' + type + '/' + name);
    TEMPLATE_CACHE.set(key, template);
  }
  return template;
}

/** The template data of one element (for tests and the Inspector). */
export function buildVillagePart(type, name) {
  return buildVillageElement(type, villageElement(type, name), CATALOGUE);
}

/** The pools of one village type: town centres (normal and abandoned), streets and houses. */
export function createVillagePools(type) {
  const pools = new TemplatePoolRegistry();
  const element = (name, weight) => new PoolElement({
    name,
    weight,
    build: () => ({
      connectors: templateFor(type, name).blocks
        .filter((block) => block.nbt && Object.prototype.hasOwnProperty.call(block.nbt, 'pool'))
        .map((block) => ({
          name: block.nbt.name, pool: block.nbt.pool, orientation: block.nbt.orientation, joint: block.nbt.joint,
          finalState: block.nbt.final_state ?? null, local: { x: block.pos[0], y: block.pos[1], z: block.pos[2] }
        }))
    })
  });
  const cat = CATALOGUE[type];
  pools.register(new TemplatePool({
    id: 'village/town_centres',
    elements: [
      ...cat.meetings.map((m) => element(m.name, MEETING_WEIGHT)),
      ...cat.meetings.map((m) => element(ABANDONED_PREFIX + m.name, ABANDONED_MEETING_WEIGHT))
    ]
  }));
  pools.register(new TemplatePool({ id: STREET_POOL, elements: [element('street', STREET_WEIGHT), element('terminus', TERMINUS_WEIGHT)] }));
  pools.register(new TemplatePool({ id: ZOMBIE_STREET_POOL, elements: [element(ABANDONED_PREFIX + 'street', STREET_WEIGHT), element(ABANDONED_PREFIX + 'terminus', TERMINUS_WEIGHT)] }));
  const zombieHouses = zombieHouseNames(type).map((name) => element(name, weightOf(villageElement(type, name))));
  pools.register(new TemplatePool({
    id: ZOMBIE_HOUSE_POOL,
    elements: [...zombieHouses, emptyElement(ABANDONED_EMPTY_PLOT_SHARE, zombieHouses.map((e) => e.weight))]
  }));
  pools.register(new TemplatePool({
    id: HOUSE_POOL,
    elements: (() => {
      const houses = [...houseEntries(type).map((e) => element(e.name, weightOf(e))), ...(cat.lamps ?? [cat.lamp]).map((l) => element(l.name, 2))];
      return [...houses, emptyElement(EMPTY_PLOT_SHARE, houses.map((e) => e.weight))];
    })()
  }));
  return pools;
}

/** The chance that one draw from a type's houses pool is a given kind of building (for the weights test). */
export function poolShare(type, predicate) {
  const entries = houseEntries(type);
  const lamps = CATALOGUE[type].lamps ?? [CATALOGUE[type].lamp];
  const total = entries.reduce((sum, e) => sum + weightOf(e), 0) + lamps.length * 2;
  return entries.filter(predicate).reduce((sum, e) => sum + weightOf(e), 0) / total;
}

function buildPiece(type, element, rotation, mirror, at) {
  const template = templateFor(type, element.name);
  const box = template.boundingBox(at, rotation, mirror);
  const connectors = template.jigsaws(rotation, mirror).map((jigsaw) => ({
    name: jigsaw.name, pool: jigsaw.pool, orientation: jigsaw.orientation, joint: jigsaw.joint, finalState: jigsaw.finalState,
    position: { x: at.x + jigsaw.local.x, y: at.y + jigsaw.local.y, z: at.z + jigsaw.local.z }
  }));
  return { box, connectors };
}

const TERRAIN_MATCHING_ROLES = new Set(['street', 'terminus']);

/**
 * Give every piece its own height from the terrain, as vanilla's jigsaw placement does.
 *
 * The jigsaw pass lays the whole village out at ONE height -- the surface at its origin -- so on a hillside the
 * uphill houses were buried and the downhill ones floated, and a village whose origin fell in a river was planned
 * entirely under water. Vanilla avoids both: streets are `terrain_matching` (each column follows the ground) and a
 * rigid building takes its height from the ground where it joins its street. The ground here is the water surface
 * where there is water, like vanilla's `WORLD_SURFACE_WG` heightmap.
 *
 * Shifting pieces vertically after layout cannot create a collision: every piece was placed at the same base height,
 * so two pieces that did not intersect were already disjoint horizontally.
 */
function seatOnTerrain(type, pieces, { surfaceY, seaLevel = null }) {
  const ground = (x, z) => {
    const h = surfaceY(x, z, 'world_surface_wg');
    return Number.isFinite(seaLevel) ? Math.max(h, seaLevel) : h;
  };
  for (const piece of pieces) {
    const box = piece.box;
    const role = villageElement(type, piece.meta.element)?.role;
    const at = piece.meta.junction ?? { x: Math.floor((box.minX + box.maxX) / 2), z: Math.floor((box.minZ + box.maxZ) / 2) };
    const baseY = ground(at.x, at.z);
    if (TERRAIN_MATCHING_ROLES.has(role)) {
      // Per column: realization lifts each column of the street by its offset from the piece's base.
      const width = box.maxX - box.minX + 1;
      const offsets = [];
      let low = Infinity; let high = -Infinity;
      for (let z = box.minZ; z <= box.maxZ; z++) {
        for (let x = box.minX; x <= box.maxX; x++) {
          const y = ground(x, z);
          offsets[(z - box.minZ) * width + (x - box.minX)] = y - baseY;
          low = Math.min(low, y); high = Math.max(high, y);
        }
      }
      piece.meta.baseY = baseY;
      piece.meta.columnOffsets = offsets;
      piece.projection = 'terrain_matching';
      piece.box = new BlockBox(box.minX, low, box.minZ, box.maxX, high + (box.maxY - box.minY), box.maxZ);
    } else {
      piece.box = box.translate(0, baseY - box.minY, 0);
    }
  }
}

export function generateVillage({ seed, chunkX, chunkZ, structureId, context }) {
  const type = VILLAGE_TYPE_OF[structureId];
  if (!type) throw new Error(structureId + ' is not a village id');
  const originX = chunkX * 16 + 2;
  const originZ = chunkZ * 16 + 2;
  const surface = context.surfaceY ? context.surfaceY(originX, originZ, 'world_surface_wg') : 70;
  const random = legacyFromLargeFeatureSeed(seed, chunkX, chunkZ);
  const pools = createVillagePools(type);

  const result = addPieces({
    random,
    startPool: pools.resolve('village/town_centres'),
    pools,
    buildPiece: (element, rotation, mirror, at) => buildPiece(type, element, rotation, mirror, at),
    maxDepth: VILLAGE_MAX_DEPTH,
    origin: { x: originX, y: surface, z: originZ },
    maxDistanceFromCentre: VILLAGE_MAX_DISTANCE
  });

  if (context.surfaceY) seatOnTerrain(type, result.pieces, context);

  const meeting = result.pieces[0];
  const centre = meeting ? { x: Math.floor((meeting.box.minX + meeting.box.maxX) / 2), z: Math.floor((meeting.box.minZ + meeting.box.maxZ) / 2) } : { x: originX, z: originZ };
  const start = new StructureStart({
    structureId, chunkX, chunkZ, pieces: result.pieces,
    biome: context.biomeAt ? context.biomeAt(centre.x, centre.z) : null,
    seed
  });
  const partMix = result.pieces.map((piece) => piece.meta.element);
  const bedsOf = (name) => villageElement(type, name)?.beds ?? 0;
  start.meta = {
    type,
    pieces: result.pieces.length,
    maxDepth: Math.max(0, ...result.pieces.map((piece) => piece.meta.depth ?? 0)),
    diagnostics: result.diagnostics,
    connected: result.isConnected(),
    biomeVariant: STYLES[type].biome,
    meetingPoint: partMix[0],
    // The vanilla way: the abandoned variant is a town centre drawn from the same pool at a small weight.
    abandoned: Boolean(partMix[0]?.startsWith(ABANDONED_PREFIX)),
    // The point vanilla checks the biome at: the centre of the meeting point.
    centre,
    partMix,
    beds: partMix.reduce((n, part) => n + bedsOf(part), 0)
  };
  return start;
}

// ---------------------------------------------------------------------------------------------------------------
// Realization.

const WOOD = /(_planks|_log|_wood|_stairs|_slab|_fence)$/;
/** Deterministic per-block chance in [0, 1). */
function chance(x, y, z, salt) {
  let h = (x * 374761393 + y * 668265263 + z * 2147483647 + salt * 1274126177) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

/**
 * What an abandoned village does to a block: the wiki's "all doors and torches are missing ... most cobblestone
 * blocks are replaced by mossy cobblestone, random blocks (particularly wood) are replaced by cobwebs, and all glass
 * panes are replaced by brown stained glass panes". Returns the new block name, `null` to leave the cell empty, or
 * the name unchanged.
 */
export function abandonBlock(name, style, x, y, z) {
  const bare = name.replace('minecraft:', '');
  if (/_door(_top)?$/.test(bare) || bare === 'torch' || bare === 'wall_torch') return null;
  if (bare === 'glass_pane') return 'minecraft:brown_stained_glass_pane';
  if (bare === 'cobblestone' && style.abandonedMossy && chance(x, y, z, 1) < 0.8) return 'minecraft:mossy_cobblestone';
  if (WOOD.test(bare) && chance(x, y, z, 2) < 0.08) return 'minecraft:cobweb';
  return name;
}

/**
 * Write a village and report what it spawns.
 *
 * Mobs come from the elements (`entities`): a villager per bed, an iron golem at the meeting point, the pen animals,
 * a camel in the desert, armour stands at the taiga armorer; cats are added at the meeting point from the village's
 * bed count. When the live world realizes a village one CHUNK at a time it passes the chunk as `clip`, and only the
 * chunk that contains a mob spawns it, so a village over four chunks does not get four copies.
 */
export function realizeVillage(start, setBlock, blockIds, { spawnMob = null, clip = null } = {}) {
  const resolver = createBlockIdResolver(blockIds || undefined);
  const type = VILLAGE_TYPE_OF[start.structureId];
  const style = STYLES[type];
  const abandoned = Boolean(start.meta?.abandoned);
  const missingBlocks = new Set();
  const chests = [];
  const spawns = [];
  let written = 0;
  const spawn = (kind, x, y, z, options) => {
    spawns.push({ type: kind, x: x + 0.5, y, z: z + 0.5, options });
    if (spawnMob && (!clip || clip.contains(x, y, z))) spawnMob(kind, x + 0.5, y, z + 0.5, { persistent: true, ...options });
  };

  for (const piece of start.pieces) {
    const name = piece.meta.element;
    if (clip && !piece.box.intersects(clip)) continue;
    const template = templateFor(type, name);
    const origin = { x: piece.box.minX, y: piece.meta.baseY ?? piece.box.minY, z: piece.box.minZ };
    const offsets = piece.meta.columnOffsets ?? null;
    const width = piece.box.maxX - piece.box.minX + 1;
    const random = new LegacyRandom(BigInt(start.seed ?? 0) + BigInt(piece.index) * 2654435761n);
    const placement = placeTemplate({
      template, origin, rotation: piece.rotation, mirror: piece.mirror,
      processors: { processors: [{ processor_type: 'minecraft:jigsaw_replacement' }] },
      random, world: null
    });
    for (const block of placement.blocks) {
      let state = block.state;
      if (abandoned) {
        const next = abandonBlock(state.name, style, block.x, block.y, block.z);
        if (next === null) state = { name: 'minecraft:air', properties: {} };
        else if (next !== state.name) state = { name: next, properties: {} };
      }
      const id = resolver.resolveState(state);
      if (id === null) { missingBlocks.add(state.name); continue; }
      if (block.nbt?.LootTable) chests.push(block.nbt.LootTable);
      // A path tile laid over water becomes the village's planks (the wiki: "Dirt paths that generate over water are
      // replaced by the village style's plank type").
      const overWater = /dirt_path$/.test(state.name) ? resolver.resolveState({ name: 'minecraft:' + style.planks, properties: {} }) : null;
      // A terrain-matching street: each column follows the ground it was planned on.
      const lift = offsets ? (offsets[(block.z - piece.box.minZ) * width + (block.x - piece.box.minX)] ?? 0) : 0;
      if (setBlock(block.x, block.y + lift, block.z, id, {
        state,
        ...(block.nbt?.LootTable ? { lootTable: block.nbt.LootTable } : {}),
        ...(overWater !== null ? { ifWater: overWater } : {})
      })) written++;
    }
    const entry = villageElement(type, name);
    if (entry?.role === 'meeting') {
      // Cats: one for every four beds in the whole village, up to five, at the meeting point.
      const cats = Math.min(MAX_VILLAGE_CATS, Math.floor((start.meta?.beds ?? 0) / BEDS_PER_CAT));
      for (const [dx, dz] of MEETING_CAT_SPOTS.slice(0, cats)) spawn('cat', piece.box.minX + dx, piece.box.minY + 1, piece.box.minZ + dz, {});
    }
    for (const entity of template.entitiesTransformed(piece.rotation, piece.mirror)) {
      let kind = entity.nbt?.type;
      if (!kind) continue;
      if (abandoned) {
        if (kind === 'iron_golem' || kind === 'camel') continue; // "they do not spawn iron golems"; camels "excluding abandoned villages"
        if (kind === 'villager') kind = 'zombie_villager';
      }
      const options = entity.nbt.equipment ? { equipment: entity.nbt.equipment } : {};
      spawn(kind, origin.x + entity.local.x, origin.y + entity.local.y, origin.z + entity.local.z, options);
    }
  }

  const count = (kind) => spawns.filter((s) => s.type === kind).length;
  return {
    written,
    pieces: start.pieces.length,
    chests: chests.length,
    chestLoot: chests,
    missingBlocks: [...missingBlocks].sort(),
    spawns,
    villagers: count('villager'),
    zombieVillagers: count('zombie_villager'),
    ironGolems: count('iron_golem'),
    cats: count('cat'),
    abandoned,
    note: 'clean-room village elements per type from the wiki descriptions; a villager per bed, an iron golem at the bell'
  };
}
